-- dbo.BesiteSeminar source

ALTER   VIEW dbo.BesiteSeminar
AS
SELECT
    integreat_seminar.OID,
    concat('https://evenementen.scoutsengidsenvlaanderen.be/Seminar/', integreat_seminar.OID) AS Url,
    integreat_seminar.Code, 
    Name,
    StartTime,
    EndTime,
    (
        SELECT Description
        FROM Integreat_SeminarCMSSchemeRow, Integreat_SeminarCMS
        WHERE Integreat_SeminarCMSSchemeRow.oid = Integreat_SeminarCMS.SeminarCMSSchemeRow
        AND Integreat_SeminarCMS.Seminar = integreat_seminar.OID
        AND Integreat_SeminarCMSSchemeRow.parentrow = 1
    ) AS PeriodName,
    StartRegistration,
    EndRegistration,
    (SELECT name FROM integreat_city WHERE OID = locationcity) AS Location,
    (
        SELECT MAX(maxparticipants)
        FROM Integreat_SeminarSession, Integreat_SeminarModule
        WHERE Integreat_SeminarSession.module = Integreat_SeminarModule.OID 
        AND Integreat_SeminarModule.seminar = integreat_seminar.OID
    ) - (
        SELECT count(*)
        FROM integreat_registration 
        WHERE status = 2 
        AND participanttype = 81480150 
        AND seminar = integreat_seminar.OID
    ) AS ParticipantsLeft
FROM integreat_seminar
WHERE GETDATE() < EndTime;


