ALTER   VIEW dbo.BesiteSeminarTerm
AS
SELECT Seminar AS SeminarOID, Description AS Term
FROM Integreat_SeminarCMSSchemeRow, Integreat_SeminarCMS
WHERE Integreat_SeminarCMSSchemeRow.oid = Integreat_SeminarCMS.SeminarCMSSchemeRow
AND Integreat_SeminarCMSSchemeRow.parentrow != 1;


