-- dbo.Integreat_vwInvoiceSeminar source

-- 00.135.211: add InternalReference to [Integreat_vwInvoiceSeminar]
ALTER VIEW [dbo].[Integreat_vwInvoiceSeminar]
			AS
			SELECT DISTINCT OID [Invoice], 
			SUBSTRING(
				(
					SELECT DISTINCT ', '+ s.Code 
					FROM dbo.Integreat_Sales_Invoice i
					left join Integreat_Sales_InvoiceDetail d on i.OID = d.Header
					left join Integreat_Seminar s on d.Seminar = s.OID
					WHERE i.OID = h.OID
					FOR XML PATH (''), root('MyString'), type).value('/MyString[1]','varchar(max)'), 3, 10000) [Seminars],
			SUBSTRING(
				(
					SELECT DISTINCT ', '+ s.Name 
					FROM dbo.Integreat_Sales_Invoice i
					left join Integreat_Sales_InvoiceDetail d on i.OID = d.Header
					left join Integreat_Seminar s on d.Seminar = s.OID
					WHERE i.OID = h.OID
					FOR XML PATH (''), root('MyString'), type).value('/MyString[1]','varchar(max)'), 3, 10000) [SeminarNames],
			SUBSTRING(
				(
					SELECT DISTINCT ', '+ p.FullName
					FROM dbo.Integreat_Sales_Invoice i
					left join Integreat_Sales_InvoiceDetail d on i.OID = d.Header
					left join Integreat_Participant p on d.Participant = p.OID
					WHERE i.OID = h.OID
					FOR XML PATH (''), root('MyString'), type).value('/MyString[1]','varchar(max)'), 3, 10000) [Participants],
			SUBSTRING(
				(
					SELECT DISTINCT ', '+ p.Code
					FROM dbo.Integreat_Sales_Invoice i
					left join Integreat_Sales_InvoiceDetail d on i.OID = d.Header
					left join Integreat_Participant p on d.Participant = p.OID
					WHERE i.OID = h.OID
					FOR XML PATH (''), root('MyString'), type).value('/MyString[1]','varchar(max)'), 3, 10000) [ParticipantCodes],
			SUBSTRING(
				(
					SELECT DISTINCT ', '+ r.Subgroup
					FROM dbo.Integreat_Sales_Invoice i
					left join Integreat_Sales_InvoiceDetail d on i.OID = d.Header
					left join Integreat_Registration r on d.Registration = r.OID
					WHERE i.OID = h.OID
					FOR XML PATH (''), root('MyString'), type).value('/MyString[1]','varchar(max)'), 3, 10000) [RegistrationSubgroup],
			SUBSTRING(
				(
					SELECT DISTINCT ', '+ d.InternalReference
					FROM dbo.Integreat_Sales_Invoice i
					left join Integreat_Sales_InvoiceDetail d on i.OID = d.Header
					WHERE i.OID = h.OID
					FOR XML PATH (''), root('MyString'), type).value('/MyString[1]','varchar(max)'), 3, 10000) [InternalReference]

			FROM Integreat_Sales_Invoice h;


-- dbo.Integreat_vwMostRecentBudgetCalculationBudget source

ALTER VIEW [dbo].[Integreat_vwMostRecentBudgetCalculationBudget]
AS
SELECT [MRBCB].[OID],
       [MRBCB].[Budget],
       [Integreat_BudgetCalculationBudget].[BudgetCalculationResult]
FROM
(
    SELECT MAX([OID]) AS [OID],
           [Budget]
    FROM [dbo].[Integreat_BudgetCalculationBudget]
    WHERE [Budget] IS NOT NULL
    GROUP BY [Budget]
) [MRBCB]
INNER JOIN [dbo].[Integreat_BudgetCalculationBudget] ON [Integreat_BudgetCalculationBudget].[OID] = [MRBCB].[OID];


