-- dbo.Integreat_vwPivot_Budgets source

ALTER VIEW [dbo].[Integreat_vwPivot_Budgets]
AS
	SELECT 
	[Integreat_BudgetCalculationBudget].[BudgetAmount] AS [BudgetAmount],
	[Integreat_BudgetCalculationResult].[AllocatedByCommitments] + [Integreat_BudgetCalculationResult].[AllocatedByRequests] + [Integreat_BudgetCalculationResult].[AllocatedByOrders] + [Integreat_BudgetCalculationResult].[AllocatedByDeliveryNotes] + [Integreat_BudgetCalculationResult].[AllocatedByInvoices] + [Integreat_BudgetCalculationResult].[AllocatedByExports] + [Integreat_BudgetCalculationResult].[AllocatedByAccounting] AS [AllocatedTotal],
	([Integreat_BudgetCalculationBudget].[BudgetAmount]) - ([Integreat_BudgetCalculationResult].[AllocatedByCommitments] + [Integreat_BudgetCalculationResult].[AllocatedByRequests] + [Integreat_BudgetCalculationResult].[AllocatedByOrders] + [Integreat_BudgetCalculationResult].[AllocatedByDeliveryNotes] + [Integreat_BudgetCalculationResult].[AllocatedByInvoices] + [Integreat_BudgetCalculationResult].[AllocatedByExports] + [Integreat_BudgetCalculationResult].[AllocatedByAccounting]) AS [FreeBudgetAmount],
	[Integreat_BudgetCalculationResult].[AllocatedByCommitments] AS [BudgetCalculationResult.AllocatedByCommitments],
	[Integreat_BudgetCalculationResult].[AllocatedByRequests] AS [BudgetCalculationResult.AllocatedByRequests],
	[Integreat_BudgetCalculationResult].[AllocatedByOrders] AS [BudgetCalculationResult.AllocatedByOrders],
	[Integreat_BudgetCalculationResult].[AllocatedByDeliveryNotes] AS [BudgetCalculationResult.AllocatedByDeliveryNotes],
	[Integreat_BudgetCalculationResult].[AllocatedByInvoices] AS [BudgetCalculationResult.AllocatedByInvoices],
	[Integreat_BudgetCalculationResult].[AllocatedByExports] AS [BudgetCalculationResult.AllocatedByExports],
	[Integreat_BudgetCalculationResult].[AllocatedByAccounting] AS [BudgetCalculationResult.AllocatedByAccounting],
	[Integreat_Budget].[Budget] AS [Budget.Budget],
	[Integreat_Period].[Code] AS [Budget.Period.Code],
	[Integreat_Period].[FromDate] AS [Budget.Period.FromDate],
	[Integreat_Period].[ToDate] AS [Budget.Period.ToDate],
	[Integreat_Period].[BookYear] AS [Budget.Period.BookYear],
	[Integreat_Period].[Closed] AS [Budget.Period.Closed],
	[GeneralAccount].[Code] AS [Budget.GeneralAccount.Code],
	[GeneralAccount].[Description] AS [Budget.GeneralAccount.Description],
	[Integreat_GeneralAccountGroupCode].[Code] AS [Budget.GeneralAccount.GroupCode.Code],
	[Integreat_GeneralAccountGroupCode].[Description] AS [Budget.GeneralAccount.GroupCode.Description],
	[Integreat_GeneralAccountGroupCode].[LookupName] AS [Budget.GeneralAccount.GroupCode.LookupName],
	[GeneralAccount].[IsAnalytical] AS [Budget.GeneralAccount.IsAnalytical],
	[GeneralAccount].[IsInvestment] AS [Budget.GeneralAccount.IsInvestment],
	[GeneralAccount].[IsCentralisation] AS [Budget.GeneralAccount.IsCentralisation],
	[GeneralAccount].[TrackUnits] AS [Budget.GeneralAccount.TrackUnits],
	[GeneralAccount].[Inactive] AS [Budget.GeneralAccount.Inactive],
	[GeneralAccount].[InactiveDate] AS [Budget.GeneralAccount.InactiveDate],
	[GeneralAccount].[AccountancyInactive] AS [Budget.GeneralAccount.AccountancyInactive],
	[GeneralAccount].[VATNonDeductiblePercentage] AS [Budget.GeneralAccount.VATNonDeductiblePercentage],
	[VatNonDeductibleGeneralAccount].[Code] AS [Budget.GeneralAccount.VatNonDeductibleGeneralAccount.Code],
	[VatNonDeductibleGeneralAccount].[Description] AS [Budget.GeneralAccount.VatNonDeductibleGeneralAccount.Description],
	[Integreat_GeneralAccountType].[Code] AS [Budget.GeneralAccount.Type.Code],
	[Integreat_GeneralAccountType].[Description] AS [Budget.GeneralAccount.Type.Description],
	[GeneralAccount].[VatBox818283] AS [Budget.GeneralAccount.VatBox818283],
	[GLDepreciationPL].[Code] AS [Budget.GeneralAccount.GLDepreciationPL.Code],
	[GLDepreciationPL].[Description] AS [Budget.GeneralAccount.GLDepreciationPL.Description],
	[GLDepreciationBS].[Code] AS [Budget.GeneralAccount.GLDepreciationBS.Code],
	[GLDepreciationBS].[Description] AS [Budget.GeneralAccount.GLDepreciationBS.Description],
	[GeneralAccount].[ReopeningInDetail] AS [Budget.GeneralAccount.ReopeningInDetail],
	[GeneralAccount].[UserField01] AS [Budget.GeneralAccount.UserField01],
	[GeneralAccount].[UserField02] AS [Budget.GeneralAccount.UserField02],
	[GeneralAccount].[UserField03] AS [Budget.GeneralAccount.UserField03],
	[GeneralAccount].[UserField04] AS [Budget.GeneralAccount.UserField04],
	[GeneralAccount].[UserField05] AS [Budget.GeneralAccount.UserField05],
	[Integreat_AnalyticalAccount].[Code] AS [Budget.AnalyticalAccount.Code],
	[Integreat_AnalyticalAccount].[Description] AS [Budget.AnalyticalAccount.Description],
	[Integreat_AnalyticalAccountGroupCode].[Code] AS [Budget.AnalyticalAccount.GroupCode.Code],
	[Integreat_AnalyticalAccountGroupCode].[Description] AS [Budget.AnalyticalAccount.GroupCode.Description],
	[Integreat_AnalyticalAccountGroupCode].[LookupName] AS [Budget.AnalyticalAccount.GroupCode.LookupName],
	[Integreat_AnalyticalAccount].[MethodOfReopening] AS [Budget.AnalyticalAccount.MethodOfReopening],
	[Integreat_AnalyticalAccount].[Inactive] AS [Budget.AnalyticalAccount.Inactive],
	[Integreat_AnalyticalAccount].[InactiveDate] AS [Budget.AnalyticalAccount.InactiveDate],
	[Integreat_AnalyticalAccount].[AccountancyInactive] AS [Budget.AnalyticalAccount.AccountancyInactive],
	[Integreat_AnalyticalAccount2].[Code] AS [Budget.AnalyticalAccount2.Code],
	[Integreat_AnalyticalAccount2].[Description] AS [Budget.AnalyticalAccount2.Description],
	[Integreat_AnalyticalAccount2].[LookupName] AS [Budget.AnalyticalAccount2.LookupName],
	[Integreat_AnalyticalAccount2].[VATOnMargin] AS [Budget.AnalyticalAccount2.VATOnMargin],
	[Integreat_AnalyticalAccount2GroupCode].[Code] AS [Budget.AnalyticalAccount2.GroupCode.Code],
	[Integreat_AnalyticalAccount2GroupCode].[Description] AS [Budget.AnalyticalAccount2.GroupCode.Description],
	[Integreat_AnalyticalAccount2GroupCode].[LookupName] AS [Budget.AnalyticalAccount2.GroupCode.LookupName],
	[Integreat_AnalyticalAccount2].[VATNonDeductiblePercentage] AS [Budget.AnalyticalAccount2.VATNonDeductiblePercentage],
	[Integreat_AnalyticalAccount2].[Inactive] AS [Budget.AnalyticalAccount2.Inactive],
	[Integreat_AnalyticalAccount2].[InactiveDate] AS [Budget.AnalyticalAccount2.InactiveDate],
	[Integreat_AnalyticalAccount2].[AccountancyInactive] AS [Budget.AnalyticalAccount2.AccountancyInactive],
	[Integreat_AnalyticalAccount3].[Code] AS [Budget.AnalyticalAccount3.Code],
	[Integreat_AnalyticalAccount3].[Description] AS [Budget.AnalyticalAccount3.Description],
	[Integreat_AnalyticalAccount3].[LookupName] AS [Budget.AnalyticalAccount3.LookupName],
	[Integreat_AnalyticalAccount3GroupCode].[Code] AS [Budget.AnalyticalAccount3.GroupCode.Code],
	[Integreat_AnalyticalAccount3GroupCode].[Description] AS [Budget.AnalyticalAccount3.GroupCode.Description],
	[Integreat_AnalyticalAccount3GroupCode].[LookupName] AS [Budget.AnalyticalAccount3.GroupCode.LookupName],
	[Integreat_AnalyticalAccount3].[VATNonDeductiblePercentage] AS [Budget.AnalyticalAccount3.VATNonDeductiblePercentage],
	[Integreat_AnalyticalAccount3].[Inactive] AS [Budget.AnalyticalAccount3.Inactive],
	[Integreat_AnalyticalAccount3].[InactiveDate] AS [Budget.AnalyticalAccount3.InactiveDate],
	[Integreat_AnalyticalAccount3].[AccountancyInactive] AS [Budget.AnalyticalAccount3.AccountancyInactive],
	[Integreat_AnalyticalAccount3].[UserField01] AS [Budget.AnalyticalAccount3.UserField01],
	[Integreat_AnalyticalAccount3].[UserField02] AS [Budget.AnalyticalAccount3.UserField02],
	[Integreat_AnalyticalAccount3].[UserField03] AS [Budget.AnalyticalAccount3.UserField03],
	[Integreat_AnalyticalAccount3].[UserField04] AS [Budget.AnalyticalAccount3.UserField04],
	[Integreat_AnalyticalAccount3].[UserField05] AS [Budget.AnalyticalAccount3.UserField05]

	FROM [dbo].[Integreat_BudgetCalculationBudget]
	LEFT OUTER JOIN [dbo].[Integreat_BudgetCalculation] ON [Integreat_BudgetCalculation].[OID] = [Integreat_BudgetCalculationBudget].[BudgetCalculation]
	LEFT OUTER JOIN [dbo].[Integreat_BudgetCalculationResult] ON [Integreat_BudgetCalculationResult].[OID] = [Integreat_BudgetCalculationBudget].[BudgetCalculationResult]
