		ELSE [Integreat_Sales_InvoiceDetail].[NettoAmount] 
	END AS [NettoAmount],
	CASE 
		WHEN [Integreat_Sales_Invoice].[DocumentType] = 1 THEN [Integreat_Sales_InvoiceDetail].[VATAmount] 
		WHEN [Integreat_Sales_Invoice].[DocumentType] = 2 AND [Integreat_Sales_InvoiceDetail].[VATAmount] > 0 THEN [Integreat_Sales_InvoiceDetail].[VATAmount] * -1
		ELSE [Integreat_Sales_InvoiceDetail].[VATAmount] 
	END AS [VATAmount],
	CASE 
		WHEN [Integreat_Sales_Invoice].[DocumentType] = 1 THEN [Integreat_Sales_InvoiceDetail].[TotalAmount] 
		WHEN [Integreat_Sales_Invoice].[DocumentType] = 2 AND [Integreat_Sales_InvoiceDetail].[TotalAmount] > 0 THEN [Integreat_Sales_InvoiceDetail].[TotalAmount] * -1
		ELSE [Integreat_Sales_InvoiceDetail].[TotalAmount] 
	END AS [TotalAmount], 
