FROM [Integreat_Sales_InvoiceDetail] 
	LEFT OUTER JOIN [Integreat_Sales_Invoice] ON [Integreat_Sales_Invoice].[OID] = [Integreat_Sales_InvoiceDetail].[Header] 
	LEFT OUTER JOIN [Integreat_Client] ON [Integreat_Client].[OID] = [Integreat_Sales_Invoice].[Client] 
	LEFT OUTER JOIN [Integreat_ClientCode] cc1 ON [Integreat_Client].[Code1] = cc1.[Code] COLLATE DATABASE_DEFAULT AND cc1.[Type] = 1
	LEFT OUTER JOIN [Integreat_ClientCode] cc2 ON [Integreat_Client].[Code2] = cc2.[Code] COLLATE DATABASE_DEFAULT AND cc2.[Type] = 2
	LEFT OUTER JOIN [Integreat_ClientCode] cc3 ON [Integreat_Client].[Code3] = cc3.[Code] COLLATE DATABASE_DEFAULT AND cc3.[Type] = 3
	LEFT OUTER JOIN [Integreat_ClientCode] cc4 ON [Integreat_Client].[Code4] = cc4.[Code] COLLATE DATABASE_DEFAULT AND cc4.[Type] = 4
	LEFT OUTER JOIN [Integreat_ClientCode] cc5 ON [Integreat_Client].[Code5] = cc5.[Code] COLLATE DATABASE_DEFAULT AND cc5.[Type] = 5
	LEFT OUTER JOIN [Integreat_ClientType] ON [Integreat_ClientType].[OID] = [Integreat_Client].[Type]
	LEFT OUTER JOIN [Integreat_NACECode] ON [Integreat_NACECode].[OID] = [Integreat_Client].[NACECode]
	LEFT OUTER JOIN [Integreat_Period] ON [Integreat_Period].[OID] = [Integreat_Sales_Invoice].[Period] 
	LEFT OUTER JOIN [Integreat_Period] AS [DetailPeriod] ON [DetailPeriod].[OID] = [Integreat_Sales_InvoiceDetail].[Period] 
	LEFT OUTER JOIN [Integreat_Currency] ON [Integreat_Currency].[OID] = [Integreat_Sales_Invoice].[DocumentCurrency] 
	LEFT OUTER JOIN [Integreat_PaymentType] ON [Integreat_PaymentType].[OID] = [Integreat_Sales_Invoice].[PaymentType] 
	LEFT OUTER JOIN [Integreat_Journal] ON [Integreat_Journal].[OID] = [Integreat_Sales_Invoice].[ExportJournal] 
	LEFT OUTER JOIN [Integreat_FixedText] ON [Integreat_FixedText].[OID] = [Integreat_Sales_Invoice].[FixedText] 
	LEFT OUTER JOIN [Integreat_Sales_InvoiceType] ON [Integreat_Sales_InvoiceType].[OID] = [Integreat_Sales_Invoice].[DocumentType] 
	LEFT OUTER JOIN [Integreat_Sales_DocumentTemplate] ON [Integreat_Sales_DocumentTemplate].[OID] = [Integreat_Sales_Invoice].[DocumentTemplate] 
	LEFT OUTER JOIN [Integreat_Country] AS [ClientCountry] ON [ClientCountry].[OID] = [Integreat_Client].[Country] 
	LEFT OUTER JOIN [Integreat_Country] AS [InvoiceCountry] ON [InvoiceCountry].[OID] = [Integreat_Sales_Invoice].[ClientCountry] 
	LEFT OUTER JOIN [Integreat_Language] AS [ClientLanguage] ON [ClientLanguage].[OID] = [Integreat_Client].[Language] 
	LEFT OUTER JOIN [Integreat_PaymentType] AS [ClientPaymentType] ON [ClientPaymentType].[OID] = [Integreat_Client].[PaymentType] 
	LEFT OUTER JOIN [Integreat_Currency] AS [ClientCurrency] ON [ClientCurrency].[OID] = [Integreat_Client].[Currency] 
	LEFT OUTER JOIN [Integreat_GeneralAccount] AS [ClientGeneralAccount] ON [ClientGeneralAccount].[OID] = [Integreat_Client].[GeneralAccount] 
	LEFT OUTER JOIN [Integreat_GeneralAccount] AS [ClientCollectiveGeneralAccount] ON [ClientCollectiveGeneralAccount].[OID] = [Integreat_Client].[CollectiveGeneralAccount] 
	LEFT OUTER JOIN [Integreat_ClientGroupCode] ON [Integreat_ClientGroupCode].[OID] = [Integreat_Client].[GroupCode] 
	LEFT OUTER JOIN [Integreat_VatNature] AS [ClientVATNature] ON [ClientVATNature].[OID] = [Integreat_Client].[VATNature] 
	LEFT OUTER JOIN [Integreat_VatNature] AS [InvoiceVATNature] ON [InvoiceVATNature].[OID] = [Integreat_Sales_Invoice].[VATNature] 
	LEFT OUTER JOIN [Integreat_ClientStatus] ON [Integreat_ClientStatus].[OID] = [Integreat_Client].[Status] 
	LEFT OUTER JOIN [Integreat_AccountCategory] ON [Integreat_AccountCategory].[OID] = [Integreat_Client].[Category] 
	LEFT OUTER JOIN [Integreat_Classification] ON [Integreat_Classification].[OID] = [Integreat_Client].[Classification] 
	LEFT OUTER JOIN [Integreat_OrganizationUnitSite] ON [Integreat_OrganizationUnitSite].[OID] = [Integreat_Sales_Invoice].[OrganizationUnitSite] 
	LEFT OUTER JOIN [Integreat_OrganizationUnit] ON [Integreat_OrganizationUnit].[OID] = [Integreat_OrganizationUnitSite].[OrganizationUnit] 
	LEFT OUTER JOIN [Integreat_OrganizationUnitType] ON [Integreat_OrganizationUnitType].[OID] = [Integreat_OrganizationUnit].[Type] 
	LEFT OUTER JOIN [Integreat_Address] ON [Integreat_Address].[OID] = [Integreat_OrganizationUnitSite].[Address] 
	LEFT OUTER JOIN [Integreat_Country] AS [OrganizationUnitCountry] ON [OrganizationUnitCountry].[OID] = [Integreat_Address].[Country] 
	LEFT OUTER JOIN [Integreat_Unit] AS [DetailUnit] ON [DetailUnit].[OID] = [Integreat_Sales_InvoiceDetail].[Unit] 
	LEFT OUTER JOIN [Integreat_Currency] AS [DetailCurrency] ON [DetailCurrency].[OID] = [Integreat_Sales_InvoiceDetail].[Currency] 
	LEFT OUTER JOIN [Integreat_Article] ON [Integreat_Article].[OID] = [Integreat_Sales_InvoiceDetail].[Article] 
	LEFT OUTER JOIN [Integreat_GeneralAccount] AS [ArticleGeneralAccountPurchase] ON [ArticleGeneralAccountPurchase].[OID] = [Integreat_Article].[Purchase_GeneralAccount]
	LEFT OUTER JOIN [Integreat_AnalyticalAccount] AS [ArticleAnalyticalAccount] ON [ArticleAnalyticalAccount].[OID] = [Integreat_Article].[Sales_AnalyticalAccount] 
	LEFT OUTER JOIN [Integreat_Unit] AS [LengthUnit] ON [LengthUnit].[OID] = [Integreat_Article].[LengthUnit] 
	LEFT OUTER JOIN [Integreat_Unit] AS [WidthUnit] ON [WidthUnit].[OID] = [Integreat_Article].[WidthUnit] 
	LEFT OUTER JOIN [Integreat_Unit] AS [HeightUnit] ON [HeightUnit].[OID] = [Integreat_Article].[HeightUnit] 
	LEFT OUTER JOIN [Integreat_Unit] AS [CapacityUnit] ON [CapacityUnit].[OID] = [Integreat_Article].[CapacityUnit] 
	LEFT OUTER JOIN [Integreat_Unit] AS [WeightUnit] ON [WeightUnit].[OID] = [Integreat_Article].[WeightUnit] 
	LEFT OUTER JOIN [Integreat_AnalyticalAccount2] AS [ArticleAnalyticalAccount2] ON [ArticleAnalyticalAccount2].[OID] = [Integreat_Article].[Sales_AnalyticalAccount2] 
	LEFT OUTER JOIN [Integreat_AnalyticalAccount3] AS [ArticleAnalyticalAccount3] ON [ArticleAnalyticalAccount3].[OID] = [Integreat_Article].[Sales_AnalyticalAccount3]
	LEFT OUTER JOIN [Integreat_GeneralAccount] AS [ArticleGeneralAccountSales] ON [ArticleGeneralAccountSales].[OID] = [Integreat_Article].[Sales_GeneralAccount] 
	LEFT OUTER JOIN [Integreat_ArticleStatus] ON [Integreat_ArticleStatus].[OID] = [Integreat_Article].[Status] 
	LEFT OUTER JOIN [Integreat_ArticleGroup] ON [Integreat_ArticleGroup].[OID] = [Integreat_Article].[ArticleGroup] 
	LEFT OUTER JOIN [Integreat_Participant] ON [Integreat_Participant].[OID] = [Integreat_Sales_InvoiceDetail].[Participant] 
	LEFT OUTER JOIN [Integreat_Country] AS [ParticipantCountry] ON [ParticipantCountry].[OID] = [Integreat_Participant].[Country] 
	LEFT OUTER JOIN [Integreat_Country] AS [ParticipantCompanyCountry] ON [ParticipantCompanyCountry].[OID] = [Integreat_Participant].[CompanyCountry] 
	LEFT OUTER JOIN [Integreat_ParticipantStatus] ON [Integreat_ParticipantStatus].[OID] = [Integreat_Participant].[Status] 
	LEFT OUTER JOIN [Integreat_Gender] ON [Integreat_Gender].[OID] = [Integreat_Participant].[Gender] 
	LEFT OUTER JOIN [Integreat_Language] AS [ParticipantLanguage] ON [ParticipantLanguage].[OID] = [Integreat_Participant].[Language] 
	LEFT OUTER JOIN [Integreat_ParticipantType] ON [Integreat_ParticipantType].[OID] = [Integreat_Participant].[Type] 
	LEFT OUTER JOIN [Integreat_Seminar] ON [Integreat_Seminar].[OID] = [Integreat_Sales_InvoiceDetail].[Seminar] 
	LEFT OUTER JOIN [Integreat_SeminarModule] ON [Integreat_SeminarModule].[OID] = [Integreat_Sales_InvoiceDetail].[SeminarModule] 
	LEFT OUTER JOIN [Integreat_SeminarSession] ON [Integreat_SeminarSession].[OID] = [Integreat_Sales_InvoiceDetail].[SeminarSession] 
	LEFT OUTER JOIN [Integreat_Registration] ON [Integreat_Registration].[OID] = [Integreat_Sales_InvoiceDetail].[Registration]
	LEFT OUTER JOIN [Integreat_SMEWallet] ON [Integreat_SMEWallet].[OID] = [Integreat_Registration].[KMOP]
	LEFT OUTER JOIN [Integreat_GeneralAccount] AS [DetailGeneralAccount] ON [DetailGeneralAccount].[OID] = [Integreat_Sales_InvoiceDetail].[GeneralAccount] 
	LEFT OUTER JOIN [Integreat_AnalyticalAccount] AS [DetailAnalyticalAccount] ON [DetailAnalyticalAccount].[OID] = [Integreat_Sales_InvoiceDetail].[AnalyticalAccount] 
	LEFT OUTER JOIN [Integreat_AnalyticalAccount2] AS [DetailAnalyticalAccount2] ON [DetailAnalyticalAccount2].[OID] = [Integreat_Sales_InvoiceDetail].[AnalyticalAccount2] 

WHERE ([Integreat_Sales_Invoice].[OID] > 0);


