	(SELECT COUNT(*) FROM [Integreat_Registration] WHERE [Participant] = [Integreat_Participant].[OID] AND [Seminar] = [Integreat_Seminar].[OID]) AS RegistrationCount

FROM [Integreat_Participant]
	LEFT OUTER JOIN [Integreat_Country] AS ParticipantCountry ON [ParticipantCountry].[OID] = [Integreat_Participant].[Country]
	LEFT OUTER JOIN [Integreat_Language] AS ParticipantLanguage ON [ParticipantLanguage].[OID] = [Integreat_Participant].[Language]
	LEFT OUTER JOIN [Integreat_ParticipantStatus] AS ParticipantStatus ON [ParticipantStatus].[OID] = [Integreat_Participant].[Status]
	LEFT OUTER JOIN [Integreat_ParticipantType] AS ParticipantType ON [ParticipantType].[OID] = [Integreat_Participant].[Type]
	LEFT OUTER JOIN [Integreat_Gender] AS ParticipantGender ON [ParticipantGender].[OID] = [Integreat_Participant].[Gender]
	LEFT OUTER JOIN [Integreat_Country] AS ParticipantCompanyCountry ON [ParticipantCompanyCountry].[OID] = [Integreat_Participant].[CompanyCountry]
	LEFT OUTER JOIN [Integreat_Registration] ON [Integreat_Registration].[Participant] = [Integreat_Participant].[OID]
	LEFT OUTER JOIN [Integreat_Seminar] ON [Integreat_Seminar].[OID] = [Integreat_Registration].[Seminar]
	LEFT OUTER JOIN [Integreat_SeminarGroup] ON [Integreat_SeminarGroup].[OID] = [Integreat_Registration].[SeminarGroup]
	LEFT OUTER JOIN [Integreat_EvaluationTemplate] ON [Integreat_EvaluationTemplate].[OID] = [Integreat_Seminar].[Template]
	LEFT OUTER JOIN [Integreat_SeminarStatus] ON [Integreat_SeminarStatus].[OID] = [Integreat_Seminar].[Status]
	LEFT OUTER JOIN [Integreat_SeminarType] ON [Integreat_SeminarType].[OID] = [Integreat_Seminar].[Type]
	LEFT OUTER JOIN [Integreat_AnalyticalAccount] ON [Integreat_AnalyticalAccount].[OID] = [Integreat_Seminar].[AnalyticalAccount]
	LEFT OUTER JOIN [Integreat_City] AS LocationCity ON [LocationCity].[OID] = [Integreat_Seminar].[LocationCity]
	LEFT OUTER JOIN [Integreat_Country] AS LocationCountry ON [LocationCountry].[OID] = [LocationCity].[Country]
	LEFT OUTER JOIN [Integreat_ParticipantType] AS RegistrationType ON [RegistrationType].[OID] = [Integreat_Registration].[ParticipantType]
	LEFT OUTER JOIN [Integreat_RegistrationFeeType] ON [Integreat_RegistrationFeeType].[OID] = [Integreat_Registration].[RegistrationFee]
	LEFT OUTER JOIN [Integreat_RegistrationStatus] ON [Integreat_RegistrationStatus].[OID] = [Integreat_Registration].[Status]
	LEFT OUTER JOIN [Integreat_SMEWallet] ON [Integreat_SMEWallet].[OID] = [Integreat_Registration].[KMOP]
	LEFT OUTER JOIN [Integreat_RegistrationSeminarSession] ON [Integreat_RegistrationSeminarSession].[Registration] = [Integreat_Registration].[OID]
	LEFT OUTER JOIN [Integreat_SeminarSession] ON [Integreat_SeminarSession].[OID] = [Integreat_RegistrationSeminarSession].[SeminarSession]
	LEFT OUTER JOIN [Integreat_City] AS SessionCity ON [SessionCity].[OID] = [Integreat_SeminarSession].[City]
	LEFT OUTER JOIN [Integreat_Country] AS SessionCountry ON [SessionCountry].[OID] = [SessionCity].[Country]
	LEFT OUTER JOIN [Integreat_SeminarModule] ON [Integreat_SeminarModule].[OID] = [Integreat_SeminarSession].[Module]
	LEFT OUTER JOIN [Integreat_Language] AS SeminarLanguage ON [SeminarLanguage].[OID] = [Integreat_Seminar].[Language]
	LEFT OUTER JOIN [Integreat_WebLink] ON [Integreat_WebLink].[OID] = [Integreat_Seminar].[WebLink]

	LEFT OUTER JOIN [Integreat_Sales_InvoiceDetail] ON [Integreat_Sales_InvoiceDetail].[Registration] = [Integreat_Registration].[OID]
	LEFT OUTER JOIN [Integreat_Sales_Invoice] ON [Integreat_Sales_Invoice].[OID] = [Integreat_Sales_InvoiceDetail].[Header]
	LEFT OUTER JOIN [Integreat_Period] ON [Integreat_Sales_Invoice].[Period] = [Integreat_Period].[OID]
	LEFT OUTER JOIN [Integreat_Currency] ON [Integreat_Sales_Invoice].[DocumentCurrency] = [Integreat_Currency].[OID]
	LEFT OUTER JOIN [Integreat_PaymentType] ON [Integreat_Sales_Invoice].[PaymentType] = [Integreat_PaymentType].[OID]
	LEFT OUTER JOIN [Integreat_Client] ON [Integreat_Sales_Invoice].[Client] = [Integreat_Client].[OID]
	LEFT OUTER JOIN [Integreat_ClientCode] cc1 ON [Integreat_Client].[Code1] COLLATE DATABASE_DEFAULT = cc1.[Code] COLLATE DATABASE_DEFAULT AND cc1.[Type] = 1
	LEFT OUTER JOIN [Integreat_ClientCode] cc2 ON [Integreat_Client].[Code2] COLLATE DATABASE_DEFAULT = cc2.[Code] COLLATE DATABASE_DEFAULT AND cc2.[Type] = 2
	LEFT OUTER JOIN [Integreat_ClientCode] cc3 ON [Integreat_Client].[Code3] COLLATE DATABASE_DEFAULT = cc3.[Code] COLLATE DATABASE_DEFAULT AND cc3.[Type] = 3
	LEFT OUTER JOIN [Integreat_ClientCode] cc4 ON [Integreat_Client].[Code4] COLLATE DATABASE_DEFAULT = cc4.[Code] COLLATE DATABASE_DEFAULT AND cc4.[Type] = 4
	LEFT OUTER JOIN [Integreat_ClientCode] cc5 ON [Integreat_Client].[Code5] COLLATE DATABASE_DEFAULT = cc5.[Code] COLLATE DATABASE_DEFAULT AND cc5.[Type] = 5
	LEFT OUTER JOIN [Integreat_Country] AS ClientCountry ON [ClientCountry].[OID] = [Integreat_Client].[Country]
	LEFT OUTER JOIN [Integreat_Language] AS ClientLanguage ON [ClientLanguage].[OID] = [Integreat_Client].[Language]
	LEFT OUTER JOIN [Integreat_PaymentType] AS ClientPaymentType ON [Integreat_Client].[PaymentType] = [ClientPaymentType].[OID]
	LEFT OUTER JOIN [Integreat_Currency] AS ClientCurrency ON [Integreat_Client].[Currency] = [ClientCurrency].[OID]
	LEFT OUTER JOIN [Integreat_GeneralAccount] AS ClientGeneralAccount ON [Integreat_Client].[GeneralAccount] = [ClientGeneralAccount].[OID]
	LEFT OUTER JOIN [Integreat_ClientGroupCode] ON [Integreat_Client].[GroupCode] = [Integreat_ClientGroupCode].[OID]
	LEFT OUTER JOIN [Integreat_VatNature] AS ClientVatNature ON [Integreat_Client].[VATNature] = [ClientVatNature].[OID]
	LEFT OUTER JOIN [Integreat_GeneralAccount] AS ClientCollectiveGeneralAccount ON [Integreat_Client].[CollectiveGeneralAccount] = [ClientCollectiveGeneralAccount].[OID]
	LEFT OUTER JOIN [Integreat_ClientStatus] ON [Integreat_Client].[Status] = [Integreat_ClientStatus].[OID]
	LEFT OUTER JOIN [Integreat_AccountCategory] ON [Integreat_Client].[Category] = [Integreat_AccountCategory].[OID]
	LEFT OUTER JOIN [Integreat_Classification] ON [Integreat_Client].[Classification] = [Integreat_Classification].[OID]
	LEFT OUTER JOIN [Integreat_ClientType] ON [Integreat_Client].[Type] = [Integreat_ClientType].[OID]
	LEFT OUTER JOIN [Integreat_NACECode] ON [Integreat_Client].[NACECode] = [Integreat_NACECode].[OID]
	LEFT OUTER JOIN [Integreat_OrganizationUnitSite] ON [Integreat_Sales_Invoice].[OrganizationUnitSite] = [Integreat_OrganizationUnitSite].[OID]
	LEFT OUTER JOIN [Integreat_OrganizationUnit] ON [Integreat_OrganizationUnitSite].[OrganizationUnit] = [Integreat_OrganizationUnit].[OID]
	LEFT OUTER JOIN [Integreat_OrganizationUnitType] ON [Integreat_OrganizationUnit].[Type] = [Integreat_OrganizationUnitType].[OID]
	LEFT OUTER JOIN [Integreat_Address] ON [Integreat_OrganizationUnitSite].[Address] = [Integreat_Address].[OID]
	LEFT OUTER JOIN [Integreat_Country] AS OrganizationUnitCountry ON [OrganizationUnitCountry].[OID] = [Integreat_Address].[Country]
	LEFT OUTER JOIN [Integreat_Journal] ON [Integreat_Sales_Invoice].[ExportJournal] = [Integreat_Journal].[OID]
	LEFT OUTER JOIN [Integreat_VatNature] AS InvoiceVatNature ON [Integreat_Sales_Invoice].[VATNature] = [InvoiceVatNature].[OID]
	LEFT OUTER JOIN [Integreat_FixedText] ON [Integreat_Sales_Invoice].[FixedText] = [Integreat_FixedText].[OID]
	LEFT OUTER JOIN [Integreat_Sales_InvoiceType] ON [Integreat_Sales_Invoice].[DocumentType] = [Integreat_Sales_InvoiceType].[OID]
	LEFT OUTER JOIN [Integreat_Country] AS InvoiceCountry ON [InvoiceCountry].[OID] = [Integreat_Sales_Invoice].[ClientCountry]
	LEFT OUTER JOIN [Integreat_Sales_DocumentTemplate] ON [Integreat_Sales_Invoice].[DocumentTemplate] = [Integreat_Sales_DocumentTemplate].[OID]

WHERE [Integreat_Participant].[OID] > 0;


