	[Integreat_SeminarSession].[Code] AS [Registration.Program.Session.Code],
	[Integreat_SeminarSession].[Name] AS [Registration.Program.Session.Name],
	[Integreat_SeminarSession].[StartTime] AS [Registration.Program.Session.StartTime],
	[Integreat_SeminarSession].[EndTime] AS [Registration.Program.Session.EndTime],
	[Integreat_SeminarSession].[Room] AS [Registration.Program.Session.Room],
	[Integreat_SeminarSession].[Floor] AS [Registration.Program.Session.Floor],
	[Integreat_SeminarSession].[Building] AS [Registration.Program.Session.Building],
	[Integreat_SeminarSession].[Street] AS [Registration.Program.Session.Street],
	[SessionCity].[Name] AS [Registration.Program.Session.City.Name],
	[SessionCity].[Postcode] AS [Registration.Program.Session.City.Postcode],
	[SessionCountry].[Name] AS [Registration.Program.Session.City.Country.Name],
	[SessionCountry].[Code] AS [Registration.Program.Session.City.Country.Code],
	[Integreat_SeminarSession].[Language] AS [Registration.Program.Session.Language],
	[Integreat_SeminarSession].[Canceled] AS [Registration.Program.Session.Canceled],
	[Integreat_SeminarSession].[LocationName] AS [Registration.Program.Session.LocationName],
	[Integreat_SeminarSession].[Hours] AS [Registration.Program.Session.Hours],
	[Integreat_SeminarSession].[HoursForCF] AS [Registration.Program.Session.HoursForCF],
	[Integreat_SeminarSession].[CancelationUntil] AS [Registration.Program.Session.CancelationUntil],

	[Integreat_SeminarModule].[Code] AS [Registration.Program.Session.Module.Code],
	[Integreat_SeminarModule].[Name] AS [Registration.Program.Session.Module.Name],
	[Integreat_SeminarModule].[StartTime] AS [Registration.Program.Session.Module.StartTime],
	[Integreat_SeminarModule].[EndTime] AS [Registration.Program.Session.Module.EndTime],

	[Integreat_RegistrationSeminarSession].[Attended] AS [Registration.Program.Attended],
	[Integreat_RegistrationSeminarSession].[AttendedWithoutRegistration] AS [Registration.Program.AttendedWithoutRegistration],
	[Integreat_RegistrationSeminarSession].[IsReserve] AS [Registration.Program.IsReserve],
	[Integreat_RegistrationSeminarSession].[CertificateReceived] AS [Registration.Program.CertificateReceived],
	[Integreat_RegistrationSeminarSession].[AttendedHoursForSession] AS [Registration.Program.AttendedHoursForSession],
	[Integreat_RegistrationSeminarSession].[HoursForCF] AS [Registration.Program.HoursForCF],
	[Integreat_RegistrationSeminarSession].[Canceled] AS [Registration.Program.Canceled],
	[Integreat_RegistrationSeminarSession].[CanceledDate] AS [Registration.Program.CanceledDate],
	[Integreat_RegistrationSeminarSession].[CanceledReason] AS [Registration.Program.CanceledReason],
	[Integreat_RegistrationSeminarSession].[ScanIn] AS [Registration.Program.ScanIn],
	[Integreat_RegistrationSeminarSession].[ScanOut] AS [Registration.Program.ScanOut],
	[Integreat_RegistrationSeminarSession].[CatchUpSessionFollowed] AS [Registration.Program.CatchUpSessionFollowed],
	[Integreat_RegistrationSeminarSession].[ReplacementSent] AS [Registration.Program.ReplacementSent],
	[Integreat_RegistrationSeminarSession].[Registered] AS [Registration.Program.Registered],
	[Integreat_RegistrationSeminarSession].[ReminderSent] AS [Registration.Program.ReminderSent],
	[Integreat_RegistrationSeminarSession].[InvoiceIn] AS [Registration.Program.InvoiceIn],
	[Integreat_RegistrationSeminarSession].[InvoiceOut] AS [Registration.Program.InvoiceOut],
	[Integreat_RegistrationSeminarSession].[CertificateType] AS [Registration.Program.CertificateType],
	[Integreat_RegistrationSeminarSession].[RegisteredOn] AS [Registration.Program.RegisteredOn],

	[Integreat_SMEWallet].[Code] AS [Registration.KMOP.Code],

	(SELECT COUNT(*) FROM [Integreat_Registration] WHERE [Participant] = [Integreat_Participant].[OID] AND [Seminar] = [Integreat_Seminar].[OID]) AS RegistrationCount

FROM [Integreat_Participant]
	LEFT OUTER JOIN [Integreat_Country] AS ParticipantCountry ON [ParticipantCountry].[OID] = [Integreat_Participant].[Country]
	LEFT OUTER JOIN [Integreat_Language] AS ParticipantLanguage ON [ParticipantLanguage].[OID] = [Integreat_Participant].[Language]
	LEFT OUTER JOIN [Integreat_ParticipantStatus] AS ParticipantStatus ON [ParticipantStatus].[OID] = [Integreat_Participant].[Status]
	LEFT OUTER JOIN [Integreat_ParticipantType] AS ParticipantType ON [ParticipantType].[OID] = [Integreat_Participant].[Type]
	LEFT OUTER JOIN [Integreat_Gender] AS ParticipantGender ON [ParticipantGender].[OID] = [Integreat_Participant].[Gender]
	LEFT OUTER JOIN [Integreat_Country] AS ParticipantCompanyCountry ON [ParticipantCompanyCountry].[OID] = [Integreat_Participant].[CompanyCountry]
	LEFT OUTER JOIN [Integreat_Registration] ON [Integreat_Registration].[Participant] = [Integreat_Participant].[OID]
	LEFT OUTER JOIN [Integreat_Seminar] ON [Integreat_Seminar].[OID] = [Integreat_Registration].[Seminar]
	LEFT OUTER JOIN [Integreat_SeminarGroup] ON [Integreat_SeminarGroup].[OID] = [Integreat_Registration].[SeminarGroup]
	LEFT OUTER JOIN [Integreat_EvaluationTemplate] ON [Integreat_EvaluationTemplate].[OID] = [Integreat_Seminar].[Template]
	LEFT OUTER JOIN [Integreat_SeminarStatus] ON [Integreat_SeminarStatus].[OID] = [Integreat_Seminar].[Status]
	LEFT OUTER JOIN [Integreat_SeminarType] ON [Integreat_SeminarType].[OID] = [Integreat_Seminar].[Type]
	LEFT OUTER JOIN [Integreat_AnalyticalAccount] ON [Integreat_AnalyticalAccount].[OID] = [Integreat_Seminar].[AnalyticalAccount]
	LEFT OUTER JOIN [Integreat_City] AS LocationCity ON [LocationCity].[OID] = [Integreat_Seminar].[LocationCity]
	LEFT OUTER JOIN [Integreat_Country] AS LocationCountry ON [LocationCountry].[OID] = [LocationCity].[Country]
	LEFT OUTER JOIN [Integreat_ParticipantType] AS RegistrationType ON [RegistrationType].[OID] = [Integreat_Registration].[ParticipantType]
	LEFT OUTER JOIN [Integreat_RegistrationFeeType] ON [Integreat_RegistrationFeeType].[OID] = [Integreat_Registration].[RegistrationFee]
	LEFT OUTER JOIN [Integreat_RegistrationStatus] ON [Integreat_RegistrationStatus].[OID] = [Integreat_Registration].[Status]
	LEFT OUTER JOIN [Integreat_SMEWallet] ON [Integreat_SMEWallet].[OID] = [Integreat_Registration].[KMOP]
	LEFT OUTER JOIN [Integreat_Sales_Invoice] ON [Integreat_Sales_Invoice].[OID] = [Integreat_SMEWallet].[Invoice]
	LEFT OUTER JOIN [Integreat_RegistrationSeminarSession] ON [Integreat_RegistrationSeminarSession].[Registration] = [Integreat_Registration].[OID]
	LEFT OUTER JOIN [Integreat_SeminarSession] ON [Integreat_SeminarSession].[OID] = [Integreat_RegistrationSeminarSession].[SeminarSession]
	LEFT OUTER JOIN [Integreat_City] AS SessionCity ON [SessionCity].[OID] = [Integreat_SeminarSession].[City]
	LEFT OUTER JOIN [Integreat_Country] AS SessionCountry ON [SessionCountry].[OID] = [SessionCity].[Country]
	LEFT OUTER JOIN [Integreat_SeminarModule] ON [Integreat_SeminarModule].[OID] = [Integreat_SeminarSession].[Module]
	LEFT OUTER JOIN [Integreat_Language] AS SeminarLanguage ON [SeminarLanguage].[OID] = [Integreat_Seminar].[Language]
	LEFT OUTER JOIN [Integreat_WebLink] ON [Integreat_WebLink].[OID] = [Integreat_Seminar].[WebLink]
	
WHERE [Integreat_Participant].[OID] > 0;


