	[Integreat_GeneralAccountGroupCode].[Description] AS [GeneralAccount.GroupCode.Name],

	[Integreat_AnalyticalAccount2].[Code] AS [AnalyticalAccount2.Code],
	[Integreat_AnalyticalAccount2].[Description] AS [AnalyticalAccount2.Description],
	[Integreat_AnalyticalAccount2GroupCode].[Code] AS [AnalyticalAccount2.GroupCode.Code],
	[Integreat_AnalyticalAccount2GroupCode].[Description] AS [AnalyticalAccount2.GroupCode.Description],

	[Integreat_AnalyticalAccount3].[Code] AS [AnalyticalAccount3.Code],
	[Integreat_AnalyticalAccount3].[Description] AS [AnalyticalAccount3.Description],
	[Integreat_AnalyticalAccount3GroupCode].[Code] AS [AnalyticalAccount3.GroupCode.Code],
	[Integreat_AnalyticalAccount3GroupCode].[Description] AS [AnalyticalAccount3.GroupCode.Description],
		
	dbo.Integreat_CalcPurchaseDocumentDetailSubAmount([Integreat_Purchase_DocumentDetail].[OID]) AS [SubAmount],
	dbo.Integreat_CalcPurchaseDocumentDetailCommercialReduction([Integreat_Purchase_DocumentDetail].[OID]) AS [CommercialReduction],
	[Integreat_Purchase_DocumentDetail].[NettoAmount] AS [NettoAmount],
	[Integreat_Purchase_DocumentDetail].[VATAmount] AS [VATAmount],
	[Integreat_Purchase_DocumentDetail].[TotalAmount] AS [TotalAmount],
		
	[AAODD].[PriceAsAmount] AS [AnalyticalAccountsOfDocumentDetail.PriceAsAmount],
	[AAODD].[Percentage] AS [AnalyticalAccountsOfDocumentDetail.Percentage],
	CASE WHEN ([AAODD].[PriceAsAmount] = 1) THEN [AAODD].[Amount] ELSE CASE WHEN ((SELECT TOP (1) ISNULL([PurchaseArticle_UnitPrice_InclVat], 0) FROM [dbo].[Integreat_Options] ORDER BY [OID]) = 1) THEN [Integreat_Purchase_DocumentDetail].[NettoAmount] * [AAODD].[Percentage] / 100 ELSE [Integreat_Purchase_DocumentDetail].[NettoAmount] * [AAODD].[Percentage] / 100 END END AS [AnalyticalAccountsOfDocumentDetail.Amount],

	[Integreat_AnalyticalAccount].[Code] AS [AnalyticalAccountsOfDocumentDetail.AnalyticalAccount.Code],
	[Integreat_AnalyticalAccount].[Description] AS [AnalyticalAccountsOfDocumentDetail.AnalyticalAccount.Description],
	[Integreat_AnalyticalAccountGroupCode].[Code] AS [AnalyticalAccountsOfDocumentDetail.AnalyticalAccount.GroupCode.Code],
	[Integreat_AnalyticalAccountGroupCode].[Description] AS [AnalyticalAccountsOfDocumentDetail.AnalyticalAccount.GroupCode.Name]

FROM    [dbo].[Integreat_Purchase_DocumentDetail]
	INNER JOIN [dbo].[Integreat_Purchase_DocumentHeader] ON [Integreat_Purchase_DocumentHeader].[OID] = [Integreat_Purchase_DocumentDetail].[Header]
	INNER JOIN [dbo].[Integreat_Purchase_DocumentType] ON [Integreat_Purchase_DocumentType].[OID] = [Integreat_Purchase_DocumentHeader].[DocumentType]
	LEFT OUTER JOIN [dbo].[Integreat_Purchase_RequestDetail] ON [Integreat_Purchase_DocumentDetail].[OID] = [Integreat_Purchase_RequestDetail].[OID]

	LEFT OUTER JOIN [dbo].[Integreat_Period] ON [Integreat_Period].[OID] = (SELECT CASE WHEN [Integreat_Purchase_DocumentType].[OID] IN (1,2,3) THEN [Integreat_Purchase_DocumentDetail].[Period] ELSE [Integreat_Purchase_DocumentHeader].[Period] END)
	LEFT OUTER JOIN [dbo].[Integreat_Article] ON [Integreat_Purchase_DocumentDetail].[Article] = [Integreat_Article].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_ArticleStatus] ON [Integreat_Article].[Status] = [Integreat_ArticleStatus].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_ArticleGroup] ON [Integreat_ArticleGroup].[OID] = [Integreat_Article].[ArticleGroup]
	LEFT OUTER JOIN [dbo].[Integreat_Status] ON [Integreat_Purchase_DocumentDetail].[Status] = [Integreat_Status].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_Unit] ON [Integreat_Purchase_DocumentDetail].[Unit] = [Integreat_Unit].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_Currency] ON [Integreat_Purchase_DocumentDetail].[Currency] = [Integreat_Currency].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_OrganizationUnitSite] ON [Integreat_Purchase_DocumentDetail].[OrganizationUnitSite] = [Integreat_OrganizationUnitSite].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_OrganizationUnit] ON [Integreat_OrganizationUnitSite].[OrganizationUnit] = [Integreat_OrganizationUnit].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_OrganizationUnitType] ON [Integreat_OrganizationUnit].[Type] = [Integreat_OrganizationUnitType].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_Address] [OrganizationUnitSiteAddress] ON [Integreat_OrganizationUnitSite].[Address] = [OrganizationUnitSiteAddress].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_Country] [OrganizationUnitSiteAddressCountry] ON [OrganizationUnitSiteAddress].[Country] = [OrganizationUnitSiteAddressCountry].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_Address] [DeliveryAddress] ON [Integreat_Purchase_DocumentDetail].[DeliveryAddress] = [DeliveryAddress].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_Country] [DeliveryAddressCountry] ON [DeliveryAddress].[Country] = [DeliveryAddressCountry].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_User] AS [Requestor] ON [Requestor].[OID] = [Integreat_Purchase_DocumentDetail].[Requestor]
	LEFT OUTER JOIN [dbo].[Integreat_User] AS [AnchorPoint] ON [AnchorPoint].[OID] = [Integreat_Purchase_DocumentDetail].[AnchorPoint]
	LEFT OUTER JOIN [dbo].[Integreat_User] AS [BudgetResponsible] ON [BudgetResponsible].[OID] = [Integreat_Purchase_DocumentDetail].[BudgetResponsible]
	LEFT OUTER JOIN [dbo].[Integreat_User] AS [FinancialController] ON [FinancialController].[OID] = [Integreat_Purchase_DocumentDetail].[FinancialController]
	LEFT OUTER JOIN [dbo].[Integreat_User] AS [PickupPerson] ON [PickupPerson].[OID] = [Integreat_Purchase_DocumentDetail].[PickupPerson]
	LEFT OUTER JOIN [dbo].[Integreat_User] AS [ContactPerson] ON [ContactPerson].[OID] = [Integreat_Purchase_DocumentDetail].[ContactPerson]
	LEFT OUTER JOIN [dbo].[Integreat_AnalyticalDistributionKey] ON [Integreat_Purchase_DocumentDetail].[AnalyticalDistributionKey] = [Integreat_AnalyticalDistributionKey].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_Unit] AS [WeightUnit] ON [WeightUnit].[OID] = [Integreat_Purchase_DocumentDetail].[WeightUnit]
	LEFT OUTER JOIN [dbo].[Integreat_Unit] AS [HeightUnit] ON [HeightUnit].[OID] = [Integreat_Purchase_DocumentDetail].[HeightUnit]
	LEFT OUTER JOIN [dbo].[Integreat_Unit] AS [WidthUnit] ON [WidthUnit].[OID] = [Integreat_Purchase_DocumentDetail].[WidthUnit]
	LEFT OUTER JOIN [dbo].[Integreat_Unit] AS [LengthUnit] ON [LengthUnit].[OID] = [Integreat_Purchase_DocumentDetail].[LengthUnit]
	LEFT OUTER JOIN [dbo].[Integreat_Unit] AS [CapacityUnit] ON [CapacityUnit].[OID] = [Integreat_Purchase_DocumentDetail].[CapacityUnit]
	LEFT OUTER JOIN [dbo].[Integreat_GeneralAccount] ON [Integreat_Purchase_DocumentDetail].[GeneralAccount] = [Integreat_GeneralAccount].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_GeneralAccountGroupCode] ON [Integreat_GeneralAccount].[GroupCode] = [Integreat_GeneralAccountGroupCode].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_Purchase_DocumentDetailAnalyticalAccount] [AAODD] ON [AAODD].[DocumentDetail] = [Integreat_Purchase_DocumentDetail].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_AnalyticalAccount] ON [Integreat_AnalyticalAccount].[OID] = [AAODD].[AnalyticalAccount]
	LEFT OUTER JOIN [dbo].[Integreat_AnalyticalAccountGroupCode] ON [Integreat_AnalyticalAccount].[GroupCode] = [Integreat_AnalyticalAccountGroupCode].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_Supplier] ON [Integreat_Supplier].[OID] = (SELECT CASE WHEN [Integreat_Purchase_DocumentType].[OID] = 1 THEN [Integreat_Purchase_RequestDetail].[Supplier] ELSE [Integreat_Purchase_DocumentHeader].[Supplier] END)
	LEFT OUTER JOIN [dbo].[Integreat_Country] [SupplierCountry] ON [Integreat_Supplier].[Country] = [SupplierCountry].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_Language] [SupplierLanguage] ON [Integreat_Supplier].[Language] = [SupplierLanguage].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_PaymentType] [SupplierPaymentType] ON [Integreat_Supplier].[PaymentType] = [SupplierPaymentType].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_Currency] [SupplierCurrency] ON [Integreat_Supplier].[Currency] = [SupplierCurrency].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_SupplierGroupCode] [SupplierGroupCode] ON [Integreat_Supplier].[GroupCode] = [SupplierGroupCode].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_VatNature] [SupplierVatNature] ON [Integreat_Supplier].[VATNature] = [SupplierVatNature].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_GeneralAccount] [SupplierGeneralAccount] ON [Integreat_Supplier].[GeneralAccount] = [SupplierGeneralAccount].[OID]
