	LEFT OUTER JOIN [dbo].[Integreat_AnalyticalAccount3GroupCode] ON [Integreat_AnalyticalAccount3].[GroupCode] = [Integreat_AnalyticalAccount3GroupCode].[OID]

WHERE [Integreat_Purchase_DocumentHeader].[DocumentType] IN (1,2,3,4);


