	CASE WHEN ([AAODD].[PriceAsAmount] = 1) THEN [AAODD].[Amount] ELSE CASE WHEN ((SELECT TOP (1) ISNULL([PurchaseArticle_UnitPrice_InclVat], 0) FROM [dbo].[Integreat_Options] ORDER BY [OID]) = 1) THEN [Integreat_Purchase_DocumentDetail].[NettoAmount] * [AAODD].[Percentage] / 100 ELSE [Integreat_Purchase_DocumentDetail].[NettoAmount] * [AAODD].[Percentage] / 100 END END AS [AnalyticalAccountsOfDocumentDetail.Amount],

