	[Integreat_AnalyticalAccountGroupCode].[Description] AS [AnalyticalAccountsOfDocumentDetail.AnalyticalAccount.GroupCode.Name]
		
FROM    [dbo].[Integreat_Purchase_DocumentDetail]
	INNER JOIN [dbo].[Integreat_Purchase_RequestDetail] ON [Integreat_Purchase_RequestDetail].[OID] = [Integreat_Purchase_DocumentDetail].[OID]
	INNER JOIN [dbo].[Integreat_Purchase_DocumentHeader] ON [Integreat_Purchase_DocumentHeader].[OID] = [Integreat_Purchase_DocumentDetail].[Header]
	INNER JOIN [dbo].[Integreat_Purchase_DocumentType] ON [Integreat_Purchase_DocumentType].[OID] = [Integreat_Purchase_DocumentHeader].[DocumentType]
	LEFT OUTER JOIN [dbo].[Integreat_Period] ON [Integreat_Purchase_DocumentDetail].[Period] = [Integreat_Period].[OID]
