	LEFT OUTER JOIN [dbo].[Integreat_ArticleGroup] ON [Integreat_ArticleGroup].[OID] = [Integreat_Article].[ArticleGroup]
	LEFT OUTER JOIN [dbo].[Integreat_Status] ON [Integreat_Purchase_DocumentDetail].[Status] = [Integreat_Status].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_Unit] ON [Integreat_Purchase_DocumentDetail].[Unit] = [Integreat_Unit].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_Currency] ON [Integreat_Purchase_DocumentDetail].[Currency] = [Integreat_Currency].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_OrganizationUnitSite] ON [Integreat_Purchase_DocumentDetail].[OrganizationUnitSite] = [Integreat_OrganizationUnitSite].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_OrganizationUnit] ON [Integreat_OrganizationUnitSite].[OrganizationUnit] = [Integreat_OrganizationUnit].[OID]
