	LEFT OUTER JOIN [dbo].[Integreat_Address] [OrganizationUnitSiteAddress] ON [Integreat_OrganizationUnitSite].[Address] = [OrganizationUnitSiteAddress].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_Country] [OrganizationUnitSiteAddressCountry] ON [OrganizationUnitSiteAddress].[Country] = [OrganizationUnitSiteAddressCountry].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_Address] [DeliveryAddress] ON [Integreat_Purchase_DocumentDetail].[DeliveryAddress] = [DeliveryAddress].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_Country] [DeliveryAddressCountry] ON [DeliveryAddress].[Country] = [DeliveryAddressCountry].[OID]
	LEFT OUTER JOIN [dbo].[Integreat_User] AS [Requestor] ON [Requestor].[OID] = [Integreat_Purchase_DocumentDetail].[Requestor]
	LEFT OUTER JOIN [dbo].[Integreat_User] AS [AnchorPoint] ON [AnchorPoint].[OID] = [Integreat_Purchase_DocumentDetail].[AnchorPoint]
	LEFT OUTER JOIN [dbo].[Integreat_User] AS [BudgetResponsible] ON [BudgetResponsible].[OID] = [Integreat_Purchase_DocumentDetail].[BudgetResponsible]
	LEFT OUTER JOIN [dbo].[Integreat_User] AS [FinancialController] ON [FinancialController].[OID] = [Integreat_Purchase_DocumentDetail].[FinancialController]
	LEFT OUTER JOIN [dbo].[Integreat_User] AS [PickupPerson] ON [PickupPerson].[OID] = [Integreat_Purchase_DocumentDetail].[PickupPerson]
	LEFT OUTER JOIN [dbo].[Integreat_User] AS [ContactPerson] ON [ContactPerson].[OID] = [Integreat_Purchase_DocumentDetail].[ContactPerson]
