	LEFT OUTER JOIN [Integreat_RegistrationFeeType] ON [Integreat_RegistrationFeeType].[OID] = [Integreat_Registration].[RegistrationFee]
	LEFT OUTER JOIN [Integreat_RegistrationStatus] ON [Integreat_RegistrationStatus].[OID] = [Integreat_Registration].[Status]
	LEFT OUTER JOIN [Integreat_SMEWallet] ON [Integreat_SMEWallet].[OID] = [Integreat_Registration].[KMOP]
	LEFT OUTER JOIN [Integreat_RegistrationSeminarSession] ON [Integreat_RegistrationSeminarSession].[Registration] = [Integreat_Registration].[OID]
	LEFT OUTER JOIN [Integreat_SeminarSession] ON [Integreat_SeminarSession].[OID] = [Integreat_RegistrationSeminarSession].[SeminarSession]
	LEFT OUTER JOIN [Integreat_City] AS SessionCity ON [SessionCity].[OID] = [Integreat_SeminarSession].[City]
	LEFT OUTER JOIN [Integreat_Country] AS SessionCountry ON [SessionCountry].[OID] = [SessionCity].[Country]
	LEFT OUTER JOIN [Integreat_SeminarModule] ON [Integreat_SeminarModule].[OID] = [Integreat_SeminarSession].[Module]
	LEFT OUTER JOIN [Integreat_Language] AS SeminarLanguage ON [SeminarLanguage].[OID] = [Integreat_Seminar].[Language]
	LEFT OUTER JOIN [Integreat_WebLink] ON [Integreat_WebLink].[OID] = [Integreat_Seminar].[WebLink]
	LEFT OUTER JOIN [Integreat_RegistrationClient] ON [Integreat_RegistrationClient].[Registration] = [Integreat_Registration].[OID]
	LEFT OUTER JOIN [Integreat_Client] ON [Integreat_Client].[OID] = [Integreat_RegistrationClient].[Client]
	LEFT OUTER JOIN [Integreat_Country] AS ClientCountry ON [ClientCountry].[OID] = [Integreat_Client].[Country]
	LEFT OUTER JOIN [Integreat_Language] AS ClientLanguage ON [ClientLanguage].[OID] = [Integreat_Client].[Language]
	LEFT OUTER JOIN [Integreat_PaymentType] ON [Integreat_PaymentType].[OID] = [Integreat_Client].[PaymentType]
	LEFT OUTER JOIN [Integreat_Currency] ON [Integreat_Currency].[OID] = [Integreat_Client].[Currency]
	LEFT OUTER JOIN [Integreat_GeneralAccount] AS ClientGeneralAccount ON [ClientGeneralAccount].[OID] = [Integreat_Client].[GeneralAccount]
	LEFT OUTER JOIN [Integreat_ClientGroupCode] ON [Integreat_ClientGroupCode].[OID] = [Integreat_Client].[GroupCode]
	LEFT OUTER JOIN [Integreat_VatNature] ON [Integreat_VatNature].[OID] = [Integreat_Client].[VATNature]
	LEFT OUTER JOIN [Integreat_GeneralAccount] AS ClientCollectiveGeneralAccount ON [ClientCollectiveGeneralAccount].[OID] = [Integreat_Client].[CollectiveGeneralAccount]
	LEFT OUTER JOIN [Integreat_ClientStatus] AS ClientStatus ON [ClientStatus].[OID] = [Integreat_Client].[Status]
	LEFT OUTER JOIN [Integreat_AccountCategory] ON [Integreat_AccountCategory].[OID] = [Integreat_Client].[Category]
	LEFT OUTER JOIN [Integreat_Classification] ON [Integreat_Classification].[OID] = [Integreat_Client].[Classification]
	LEFT OUTER JOIN [Integreat_ClientType] AS ClientType ON [ClientType].[OID] = [Integreat_Client].[Type]
	LEFT OUTER JOIN [Integreat_ClientType] AS RegistrationClientType ON [RegistrationClientType].[OID] = [Integreat_RegistrationClient].[ClientType]
	LEFT OUTER JOIN [Integreat_NACECode] ON [Integreat_NACECode].[OID] = [Integreat_Client].[NACECode]
	
WHERE [Integreat_Participant].[OID] > 0;


