	[Integreat_SeminarModule].[HasReduction] AS [Module.HasReduction],
	[Integreat_SeminarModule].[ReductionPerSession] AS [Module.ReductionPerSession],
	[Integreat_SeminarModule].[NumberOfSessions] AS [Module.NumberOfSessions],
	[Integreat_SeminarModule].[ReductionIsPercentage] AS [Module.ReductionIsPercentage],
	[Integreat_SeminarModule].[ReductionAmount] AS [Module.ReductionAmount],
	[Integreat_SeminarModule].[UseRegistrationLimits] AS [Module.UseRegistrationLimits],
	[Integreat_SeminarModule].[MinimumNumberOfSessions] AS [Module.MinimumNumberOfSessions],
	[Integreat_SeminarModule].[MaximumNumberOfSessions] AS [Module.MaximumNumberOfSessions],

	[Integreat_SeminarSession].[Code] AS [Session.Code],
	[Integreat_SeminarSession].[Name] AS [Session.Name],
	[Integreat_SeminarSession].[Date] AS [Session.Date],
	[Integreat_SeminarSession].[StartTime] AS [Session.StartTime],
	[Integreat_SeminarSession].[EndTime] AS [Session.EndTime],
	[Integreat_SeminarSession].[Room] AS [Session.Room],
	[Integreat_SeminarSession].[Floor] AS [Session.Floor],
	[Integreat_SeminarSession].[Mandatory] AS [Session.Mandatory],
	[Integreat_SeminarSession].[MaxParticipants] AS [Session.MaxParticipants],
	[Integreat_SeminarSession].[MinParticipants] AS [Session.MinParticipants],
	[Integreat_SeminarSession].[Description] AS [Session.Description],
	[Integreat_SeminarSession].[Building] AS [Session.Building],
	[Integreat_SeminarSession].[Street] AS [Session.Street],
	[SessionCity].[Name] AS [Session.City.Name],
	[SessionCity].[Postcode] AS [Session.City.Postcode],
	[SessionCountry].[Name] AS [Session.City.Country.Name],
	[SessionCountry].[Code] AS [Session.City.Country.Code],
	[SessionLanguage].[Code] AS [Session.Language.Code],
	[Integreat_SeminarSession].[Canceled] AS [Session.Canceled],
	[Integreat_SeminarSession].[TrainingVoucher] AS [Session.TrainingVoucher],
	[Integreat_SeminarSession].[SMEWallet] AS [Session.SMEWallet],
	[Integreat_SeminarSession].[EducativeLeave] AS [Session.EducativeLeave],
	[Integreat_SeminarSession].[LocationName] AS [Session.LocationName],
	[Integreat_SeminarSession].[LocationWebsite] AS [Session.LocationWebsite],
	[Integreat_SeminarSession].[LocationRoutePlan] AS [Session.LocationRoutePlan],
	[Integreat_SeminarSession].[RequiredWhenConditionsMet] AS [Session.RequiredWhenConditionsMet],
	[Integreat_SeminarSession].[DefaultSessionFullAction] AS [Session.DefaultSessionFullAction],
	[Integreat_SeminarSession].[Hours] AS [Session.Hours],
	[Integreat_SeminarSession].[HoursForCF] AS [Session.HoursForCF],
	[Integreat_SeminarSession].[CancelationUntil] AS [Session.CancelationUntil]

	FROM [Integreat_SeminarSession]
	LEFT OUTER JOIN [Integreat_SeminarModule] ON [Integreat_SeminarModule].[OID] = [Integreat_SeminarSession].[Module]
	LEFT OUTER JOIN [Integreat_Seminar] ON [Integreat_Seminar].[OID] = [Integreat_SeminarModule].[Seminar]
	LEFT OUTER JOIN [Integreat_EvaluationTemplate] ON [Integreat_EvaluationTemplate].[OID] = [Integreat_Seminar].[Template]
	LEFT OUTER JOIN [Integreat_SeminarStatus] ON [Integreat_SeminarStatus].[OID] = [Integreat_Seminar].[Status]
	LEFT OUTER JOIN [Integreat_SeminarType] ON [Integreat_SeminarType].[OID] = [Integreat_Seminar].[Type]
	LEFT OUTER JOIN [Integreat_AnalyticalAccount] ON [Integreat_AnalyticalAccount].[OID] = [Integreat_Seminar].[AnalyticalAccount]
	LEFT OUTER JOIN [Integreat_City] AS LocationCity ON [LocationCity].[OID] = [Integreat_Seminar].[LocationCity]
	LEFT OUTER JOIN [Integreat_Country] AS LocationCountry ON [LocationCountry].[OID] = [LocationCity].[Country]
	LEFT OUTER JOIN [Integreat_Language] AS SeminarLanguage ON [SeminarLanguage].[OID] = [Integreat_Seminar].[Language]
	LEFT OUTER JOIN [Integreat_WebLink] ON [Integreat_WebLink].[OID] = [Integreat_Seminar].[WebLink]
	LEFT OUTER JOIN [Integreat_City] AS SessionCity ON [SessionCity].[OID] = [Integreat_SeminarSession].[City]
	LEFT OUTER JOIN [Integreat_Country] AS SessionCountry ON [SessionCountry].[OID] = [SessionCity].[Country]
	LEFT OUTER JOIN [Integreat_Language] AS SessionLanguage ON [SessionLanguage].[OID] = [Integreat_SeminarSession].[Language]

	WHERE [Integreat_SeminarSession].[OID] > 0;


-- dbo.Integreat_vwRegistrationClient source

ALTER VIEW [dbo].[Integreat_vwRegistrationClient]
					AS
					SELECT DISTINCT OID [Registration], 
					SUBSTRING(
						   (
								  SELECT DISTINCT ', '+ c.Code + ' (' + CAST(rc.Percentage as NVARCHAR(10)) + '%)'
								  FROM dbo.Integreat_Registration r
								  left join Integreat_RegistrationClient rc on r.OID = rc.Registration
								  left join Integreat_Client c on rc.Client = c.OID
								  WHERE r.Code = h.Code AND rc.Selected = 1
								  FOR XML PATH (''), root('MyString'), type).value('/MyString[1]','varchar(max)')
						   , 3, 10000) [Clients],
					SUBSTRING(
						   (
								  SELECT DISTINCT ', '+ c.CompanyName + ' (' + CAST(rc.Percentage as NVARCHAR(10)) + '%)'
								  FROM dbo.Integreat_Registration r
								  left join Integreat_RegistrationClient rc on r.OID = rc.Registration
								  left join Integreat_Client c on rc.Client = c.OID
								  WHERE r.Code = h.Code AND rc.Selected = 1
								  FOR XML PATH (''), root('MyString'), type).value('/MyString[1]','varchar(max)')
						   , 3, 10000) [ClientNames],
					SUBSTRING(
						   (
								  SELECT DISTINCT ', '+ CAST(c.OID as NVARCHAR(20))
								  FROM dbo.Integreat_Registration r
								  left join Integreat_RegistrationClient rc on r.OID = rc.Registration
								  left join Integreat_Client c on rc.Client = c.OID
								  WHERE r.Code = h.Code AND rc.Selected = 1
								  FOR XML PATH (''), root('MyString'), type).value('/MyString[1]','varchar(max)')
						   , 3, 10000) [ClientOIDs]
					FROM Integreat_Registration h;


