-- dbo.Integreat_vwRegistrationSessionDates source

ALTER VIEW [dbo].[Integreat_vwRegistrationSessionDates]
			AS
			SELECT DISTINCT [OID] [Registration], 
			SUBSTRING(
				(
					SELECT ', '+ CONVERT(VARCHAR(10), ISNULL(T.[Date], ''), 103)
					FROM 
					(
						SELECT DISTINCT DATEADD(DAY, DATEDIFF(DAY, 0, s.[StartTime]), 0) as [Date]
						FROM Integreat_RegistrationSeminarSession rs 
						left join Integreat_SeminarSession s on rs.[SeminarSession] = s.[OID]
						WHERE rs.[Registration] = h.[OID] AND rs.[Registered] = 1 AND rs.[Canceled] = 0 AND s.[StartTime] IS NOT NULL
					) as T
					FOR XML PATH ('')
				), 3, 10000) [SessionDates],
				SUBSTRING(
				(
					SELECT ', '+ CONVERT(VARCHAR(10), T.[Date], 103) + ' '  + convert(VARCHAR(5), T.[Date], 14) + ': ' + T.[Session]
					FROM 
					(
						SELECT DISTINCT s.[StartTime] as [Date], s.[Name] as [Session]
						FROM Integreat_RegistrationSeminarSession rs 
						left join Integreat_SeminarSession s on rs.[SeminarSession] = s.[OID]
						WHERE rs.[Registration] = h.[OID] AND rs.[Registered] = 1 AND rs.[Canceled] = 0
					) as T
					FOR XML PATH ('')
				), 3, 10000) [SessionNames],
				(
					select min(ss.[StartTime]) as Res0 
					from ([dbo].[Integreat_RegistrationSeminarSession] rss 
					inner join [dbo].[Integreat_SeminarSession] ss on (rss.[SeminarSession] = ss.[OID])) 
					where h.[OID] = rss.[Registration] and rss.[Registered] = 1 AND rss.[Canceled] = 0 AND ss.[StartTime] IS NOT NULL
				) [FirstSessionDate],
				SUBSTRING(
				(
					SELECT ', '+ T.[Description]
					FROM 
					(
						SELECT DISTINCT [Description], ParentRow, RowNr
						FROM dbo.Integreat_Seminar s
						left join Integreat_SeminarCMS c on s.[OID] = c.[Seminar]
						left join Integreat_SeminarCMSSchemeRow cr on c.[SeminarCMSSchemeRow] = cr.[OID]
						WHERE s.[OID] = h.[OID] AND cr.[OID] IN (SELECT [DecomposedCMSRows] FROM [dbo].[Integreat_GetCMSDecomposition]((SELECT TOP 1 [CMS_Departments] FROM Integreat_Options)))
					) 
					as T
					ORDER BY T.ParentRow, T.RowNr
					FOR XML PATH ('')
				), 3, 10000) [SeminarDepartments]
			FROM Integreat_Registration h;


-- dbo.Integreat_vwSeminarSessionDates source

ALTER VIEW [dbo].[Integreat_vwSeminarSessionDates]
			AS
			SELECT DISTINCT OID [Seminar], 
			SUBSTRING(
				(
					SELECT ', '+ CONVERT(VARCHAR(10), T.[Date], 103)
					FROM 
					(
						SELECT DISTINCT DATEADD(DAY, DATEDIFF(DAY, 0, s2.[StartTime]), 0) as [Date]
						FROM dbo.Integreat_Seminar s
						left join Integreat_SeminarModule m on s.OID = m.Seminar
						left join Integreat_SeminarSession s2 on m.OID = s2.Module
						WHERE s.OID = h.OID AND s2.[StartTime] IS NOT NULL
					) as T
					FOR XML PATH ('')
				), 3, 10000) [SessionDates],
			SUBSTRING(
				(
					SELECT ', '+ T.[Description]
					FROM 
					(
						SELECT DISTINCT [Description], ParentRow, RowNr
						FROM dbo.Integreat_Seminar s
						left join Integreat_SeminarCMS c on s.[OID] = c.[Seminar]
						left join Integreat_SeminarCMSSchemeRow cr on c.[SeminarCMSSchemeRow] = cr.[OID]
						WHERE s.[OID] = h.[OID] AND cr.[OID] IN (SELECT [DecomposedCMSRows] FROM [dbo].[Integreat_GetCMSDecomposition]((SELECT TOP 1 [CMS_Departments] FROM Integreat_Options)))
					) 
					as T
					ORDER BY T.ParentRow, T.RowNr
					FOR XML PATH (''), TYPE
				).value('.', 'VARCHAR(MAX)'), 3, 10000) [SeminarDepartments],
			SUBSTRING(
				(
					SELECT ', '+ T.[Description]
					FROM 
					(
						SELECT DISTINCT [Description], ParentRow, RowNr
						FROM dbo.Integreat_Seminar s
						left join Integreat_SeminarCMS c on s.[OID] = c.[Seminar]
						left join Integreat_SeminarCMSSchemeRow cr on c.[SeminarCMSSchemeRow] = cr.[OID]
						WHERE s.[OID] = h.[OID] AND cr.[OID] IN (SELECT [DecomposedCMSRows] FROM [dbo].[Integreat_GetCMSDecomposition]((SELECT TOP 1 [CMS_Interests] FROM Integreat_Options)))
					) 
					as T
					ORDER BY T.ParentRow, T.RowNr
					FOR XML PATH (''), TYPE
				).value('.', 'VARCHAR(MAX)'), 3, 10000) [SeminarInterests],
			SUBSTRING(
				(
					SELECT ', '+ T.[Description]
					FROM 
					(
						SELECT DISTINCT [Description], ParentRow, RowNr
						FROM dbo.Integreat_Seminar s
						left join Integreat_SeminarCMS c on s.[OID] = c.[Seminar]
						left join Integreat_SeminarCMSSchemeRow cr on c.[SeminarCMSSchemeRow] = cr.[OID]
						WHERE s.[OID] = h.[OID] AND cr.[OID] IN (SELECT [DecomposedCMSRows] FROM [dbo].[Integreat_GetCMSDecomposition]((SELECT TOP 1 [CMS_EducationTypes] FROM Integreat_Options)))
					) 
					as T
					ORDER BY T.ParentRow, T.RowNr
					FOR XML PATH (''), TYPE
				).value('.', 'VARCHAR(MAX)'), 3, 10000) [SeminarEducationTypes],
			SUBSTRING(
				(
					SELECT ', '+ T.[Description]
					FROM 
					(
						SELECT DISTINCT [Description], ParentRow, RowNr
						FROM dbo.Integreat_Seminar s
						left join Integreat_SeminarCMS c on s.[OID] = c.[Seminar]
						left join Integreat_SeminarCMSSchemeRow cr on c.[SeminarCMSSchemeRow] = cr.[OID]
						WHERE s.[OID] = h.[OID] AND cr.[OID] IN (SELECT [DecomposedCMSRows] FROM [dbo].[Integreat_GetCMSDecomposition]((SELECT TOP 1 [CMS_Themes] FROM Integreat_Options)))
					) 
					as T
					ORDER BY T.ParentRow, T.RowNr
					FOR XML PATH (''), TYPE
				).value('.', 'VARCHAR(MAX)'), 3, 10000) [SeminarThemes],
			SUBSTRING(
				(
					SELECT ', '+ T.[Code]
					FROM 
					(
						SELECT DISTINCT t.[Code]
						FROM dbo.Integreat_Seminar s
						left join Integreat_Seminar_SeminarTag st on s.[OID] = st.[Seminars]
						left join Integreat_SeminarTag t on st.[Tags] = t.[OID]
						WHERE s.[OID] = h.[OID]
					) 
					as T
					ORDER BY T.Code
					FOR XML PATH (''), TYPE
				).value('.', 'VARCHAR(MAX)'), 3, 10000) [SeminarTags]
			FROM Integreat_Seminar h;


