		FROM Integreat_Sales_Subscription h;


-- dbo.Integreat_vwSupplierBankAccountChanges source

ALTER VIEW [dbo].[Integreat_vwSupplierBankAccountChanges]
	AS
	SELECT [SupplierBankAccountChanges].[Source],
		   [SupplierBankAccountChanges].[TimeStamp],
		   [SupplierBankAccountChanges].[User],
		   [SupplierBankAccountChanges].[SupplierCode],
		   [SupplierBankAccountChanges].[SupplierName],
		   [SupplierBankAccountChanges].[SupplierCompanyNumber],
		   [SupplierBankAccountChanges].[Action],
		   [SupplierBankAccountChanges].[OldValue],
		   [SupplierBankAccountChanges].[NewValue]
	FROM 
	(
		SELECT 'ProCure' AS [Source],
			   [Integreat_Log].[TimeStamp] AS [TimeStamp],
			   [Integreat_Log].[FullName] AS [User],
			   [Integreat_Supplier].[Code] AS [SupplierCode],
			   [Integreat_Supplier].[CompanyName] AS [SupplierName],
			   [Integreat_Supplier].[CompanyNumber] AS [SupplierCompanyNumber],
			   CASE
				   WHEN ([Integreat_Log].[OldValue] = N' ()') THEN 'Nieuw'
				   WHEN (LEN([Integreat_Log].[NewValue]) = 0) THEN 'Verwijderen'
				   ELSE 'Wijzigen'
			   END AS [Action],
			   CASE
				   WHEN ([Integreat_Log].[OldValue] = N' ()') THEN ''	-- Nieuw
				   WHEN (LEN([Integreat_Log].[NewValue]) = 0) THEN CASE WHEN (LEN([Integreat_Log].[OldValue]) - CHARINDEX(' - ', [Integreat_Log].[OldValue]) - 2 > 0) THEN RIGHT([Integreat_Log].[OldValue], LEN([Integreat_Log].[OldValue]) - CHARINDEX(' - ', [Integreat_Log].[OldValue]) - 2) ELSE '' END	-- Verwijderen
				   ELSE LEFT([Integreat_Log].[OldValue], CHARINDEX(' (', [Integreat_Log].[OldValue]))	-- Wijzigen
			   END AS [OldValue],
			   LEFT([Integreat_Log].[NewValue], CHARINDEX(' (', [Integreat_Log].[NewValue])) AS [NewValue]
		FROM [dbo].[Integreat_Supplier] WITH ( NOLOCK )
			INNER JOIN [dbo].[Integreat_SupplierLog] WITH ( NOLOCK ) ON [Integreat_SupplierLog].[Supplier] = [Integreat_Supplier].[OID]
			INNER JOIN [dbo].[Integreat_Log] WITH ( NOLOCK ) ON [Integreat_Log].[OID] = [Integreat_SupplierLog].[OID]
		WHERE [Integreat_Log].[Description] IN ( N'Bankrekening', N'Bankrekening - Bankrekeningnummer' )

		UNION ALL

		SELECT 'ProCure' AS [Source],
			   [Integreat_Log].[TimeStamp] AS [TimeStamp],
			   [Integreat_Log].[FullName] AS [User],
			   [Integreat_Supplier].[Code] AS [SupplierCode],
			   [Integreat_Supplier].[CompanyName] AS [SupplierName],
			   [Integreat_Supplier].[CompanyNumber] AS [SupplierCompanyNumber],
			   'Leverancierstatus Concept --> Actief' AS [Action],
			   '' AS [OldValue],
			   [Integreat_SupplierBankAccounts].[BankAccountNumber] AS [NewValue]
		FROM [dbo].[Integreat_Supplier] WITH ( NOLOCK )
			INNER JOIN [dbo].[Integreat_SupplierLog] WITH ( NOLOCK ) ON [Integreat_SupplierLog].[Supplier] = [Integreat_Supplier].[OID]
			INNER JOIN [dbo].[Integreat_Log] WITH ( NOLOCK ) ON [Integreat_Log].[OID] = [Integreat_SupplierLog].[OID]
			INNER JOIN [dbo].[Integreat_SupplierBankAccounts] WITH ( NOLOCK ) ON [Integreat_SupplierBankAccounts].[Supplier] = [Integreat_Supplier].[OID]
		WHERE [Integreat_Log].[Description] = 'Status'
		AND [Integreat_Log].[OldValue] = 'Concept'
		AND [Integreat_Log].[NewValue] = 'Actief'
		AND [Integreat_SupplierBankAccounts].[IsActive] = 1

	) AS [SupplierBankAccountChanges];


