-- dbo.Integreat_vwVatDeclarationDetail625 source

ALTER VIEW [dbo].[Integreat_vwVatDeclarationDetail625] AS
--	Periodic VAT declaration  /  Periodieke btw-aangifte  /  Déclaration TVA périodique
SELECT
	[Integreat_Journal].[OID] AS [JournalOID],
	[Integreat_Journal].[Code] AS [JournalCode],
	[Integreat_Journal].[Description] AS [JournalDescription],
	[Integreat_Period].[OID] AS [PeriodOID],
	[Integreat_Period].[Code] AS [PeriodCode],
	[Integreat_Accounting_TransactionHeader].[Number] AS [TransactionNumber],
	[Integreat_Client].[OID] AS [ClientOID],
	[Integreat_Client].[Code] AS [ClientCode],
	[Integreat_Client].[CompanyName] AS [ClientCompanyName],
	[Integreat_Supplier].[OID] AS [SupplierOID],
	[Integreat_Supplier].[Code] AS [SupplierCode],
	[Integreat_Supplier].[CompanyName] AS [SupplierCompanyName],
	[Integreat_GeneralAccount].[OID] AS [GeneralAccountOID],
	[Integreat_GeneralAccount].[Code] AS [GeneralAccountCode],
	[Integreat_GeneralAccount].[Description] AS [GeneralAccountDescription],
	[Integreat_AnalyticalAccount].[OID] AS [AnalyticalAccount1OID],
	[Integreat_AnalyticalAccount].[Code] AS [AnalyticalAccount1Code],
	[Integreat_AnalyticalAccount].[Description] AS [AnalyticalAccount1Description],
	[Integreat_AnalyticalAccount2].[OID] AS [AnalyticalAccount2OID],
	[Integreat_AnalyticalAccount2].[Code] AS [AnalyticalAccount2Code],
	[Integreat_AnalyticalAccount2].[Description] AS [AnalyticalAccount2Description],
	[Integreat_AnalyticalAccount3].[OID] AS [AnalyticalAccount3OID],
	[Integreat_AnalyticalAccount3].[Code] AS [AnalyticalAccount3Code],
	[Integreat_AnalyticalAccount3].[Description] AS [AnalyticalAccount3Description],
	[Integreat_VatCode].[OID] AS [VatCodeOID],
	[Integreat_VatCode].[Code] AS [VatCodeCode],
	[Integreat_Accounting_TransactionDetail].[OID] AS [TransactionDetailOID],
	[Integreat_Accounting_TransactionDetail].[VATPercentage] AS [VATPercentage],
	[Integreat_Accounting_TransactionDetail].[VATNonDeductiblePercentage] AS [VATNonDeductiblePercentage],
	[Integreat_Accounting_TransactionDetail].[AmountDC] AS [AmountDC],
	[Integreat_Accounting_TransactionDetail].[VATBaseAmountDC] AS [VATBaseAmountDC],
	[Integreat_VatBox].[OID] AS [VatBoxOID],
	[Integreat_VatBox].[Code] AS [VatBoxCode],
	[Integreat_VatBox].[Description] AS [VatBoxDescription],
	[Integreat_VatBox].[Sign] AS [VatBoxSign],
	[Integreat_VatBox].[TypeAmount] AS [VatBoxTypeAmount],
	CASE WHEN [Integreat_Accounting_TransactionHeader].[Type] IN (30, 35) THEN
		CASE WHEN [Integreat_VatBox].[TypeAmount] = 1 THEN
			[Integreat_Accounting_TransactionDetail].[AmountDC] * [Integreat_VatBox].[Sign] * -1
		ELSE
			[Integreat_Accounting_TransactionDetail].[VATBaseAmountDC] * [Integreat_VatBox].[Sign] * -1
		END
	ELSE
		CASE WHEN [Integreat_VatBox].[TypeAmount] = 1 THEN
			[Integreat_Accounting_TransactionDetail].[AmountDC] * [Integreat_VatBox].[Sign]
		ELSE
			[Integreat_Accounting_TransactionDetail].[VATBaseAmountDC] * [Integreat_VatBox].[Sign]
		END
	END AS [VatBoxAmount]

FROM [dbo].[Integreat_Accounting_TransactionHeader]
INNER JOIN [dbo].[Integreat_Journal] ON [Integreat_Journal].[OID] = [Integreat_Accounting_TransactionHeader].[Journal]
INNER JOIN [dbo].[Integreat_Period] ON [Integreat_Period].[OID] = [Integreat_Accounting_TransactionHeader].[Period]
INNER JOIN [dbo].[Integreat_Accounting_TransactionDetail] ON [Integreat_Accounting_TransactionDetail].[Header] = [Integreat_Accounting_TransactionHeader].[OID]
LEFT OUTER JOIN [dbo].[Integreat_Client] ON [Integreat_Client].[OID] = [Integreat_Accounting_TransactionDetail].[Client]
LEFT OUTER JOIN [dbo].[Integreat_Supplier] ON [Integreat_Supplier].[OID] = [Integreat_Accounting_TransactionDetail].[Supplier]
INNER JOIN [dbo].[Integreat_GeneralAccount] ON [Integreat_GeneralAccount].[OID] = [Integreat_Accounting_TransactionDetail].[GeneralAccount]
INNER JOIN [dbo].[Integreat_VatCode] ON [Integreat_VatCode].[OID] = [Integreat_Accounting_TransactionDetail].[VATCode]
INNER JOIN [dbo].[Integreat_VatCodeBox] ON [Integreat_VatCodeBox].[VatCode] = [Integreat_VatCode].[OID] AND [Integreat_VatCodeBox].[Type] = [Integreat_Accounting_TransactionDetail].[VATType]
INNER JOIN [dbo].[Integreat_VatBox] ON [Integreat_VatBox].[OID] = [Integreat_VatCodeBox].[VatBox] AND [Integreat_VatBox].[Code] NOT IN (N'81', N'82', N'83')
LEFT OUTER JOIN [dbo].[Integreat_AnalyticalAccount] ON [Integreat_AnalyticalAccount].[OID] = [Integreat_Accounting_TransactionDetail].[AnalyticalAccount1]
LEFT OUTER JOIN [dbo].[Integreat_AnalyticalAccount2] ON [Integreat_AnalyticalAccount2].[OID] = [Integreat_Accounting_TransactionDetail].[AnalyticalAccount2]
