	[Integreat_Accounting_TransactionDetail].[VATPercentage] AS [VATPercentage],
	[Integreat_Accounting_TransactionDetail].[VATNonDeductiblePercentage] AS [VATNonDeductiblePercentage],
	[Integreat_Accounting_TransactionDetail].[AmountDC] AS [AmountDC],
	[Integreat_Accounting_TransactionDetail].[VATBaseAmountDC] AS [VATBaseAmountDC],
	[Integreat_VatBox].[OID] AS [VatBoxOID],
	[Integreat_VatBox].[Code] AS [VatBoxCode],
	[Integreat_VatBox].[Description] AS [VatBoxDescription],
	[Integreat_VatBox].[Sign] AS [VatBoxSign],
	[Integreat_VatBox].[TypeAmount] AS [VatBoxTypeAmount],
	CASE WHEN [Integreat_Accounting_TransactionDetail].[VATType] IN (42, 47) THEN
		[Integreat_Accounting_TransactionDetail].[AmountDC]
	ELSE
		[Integreat_Accounting_TransactionDetail].[VATBaseAmountDC]
	END AS [VatBoxAmount]

FROM [dbo].[Integreat_Accounting_TransactionHeader]
INNER JOIN [dbo].[Integreat_Journal] ON [Integreat_Journal].[OID] = [Integreat_Accounting_TransactionHeader].[Journal]
INNER JOIN [dbo].[Integreat_Period] ON [Integreat_Period].[OID] = [Integreat_Accounting_TransactionHeader].[Period]
