INNER JOIN [dbo].[Integreat_VatCode] ON [Integreat_VatCode].[OID] = [Integreat_Accounting_TransactionDetail].[VATCode]
INNER JOIN [dbo].[Integreat_VatCodeBox] ON [Integreat_VatCodeBox].[VatCode] = [Integreat_VatCode].[OID] AND [Integreat_VatCodeBox].[Type] = [Integreat_Accounting_TransactionDetail].[VATType]
INNER JOIN [dbo].[Integreat_VatBox] ON [Integreat_VatBox].[OID] = [Integreat_VatCodeBox].[VatBox] AND [Integreat_VatBox].[Code] IN (N'81', N'82', N'83') AND [Integreat_VatBox].[TypePurchase] = [Integreat_GeneralAccount].[VatBox818283]
