-- dbo.Integreat_vwYearBudget source

ALTER VIEW [dbo].[Integreat_vwYearBudget]
AS
SELECT	*
FROM	( SELECT	[Integreat_Period].[BookYear] AS [BookYear] ,
					'P_' + RIGHT([Integreat_Period].[Code], 2) AS [Period] ,
					[Integreat_Budget].[BudgetType] ,
					[Integreat_Budget].[BudgetScenario] ,
					[Integreat_Budget].[GeneralAccount] ,
					[Integreat_Budget].[AnalyticalAccount] ,
					[Integreat_Budget].[AnalyticalAccount2] ,
					[Integreat_Budget].[AnalyticalAccount3] ,
					[Integreat_BudgetGroupAccount].[BudgetGroup] ,
					[Integreat_Budget].[Budget] AS [BudgetValue]
		  FROM		[dbo].[Integreat_Budget]
					INNER JOIN [dbo].[Integreat_Period] ON [Integreat_Period].[OID] = [Integreat_Budget].[Period]
					LEFT OUTER JOIN [dbo].[Integreat_BudgetGroupAccount] ON [Integreat_BudgetGroupAccount].[GeneralAccount] = [Integreat_Budget].[GeneralAccount]
																		  AND [Integreat_BudgetGroupAccount].[AnalyticalAccount] = [Integreat_Budget].[AnalyticalAccount]
		) [src]
PIVOT
		( SUM([src].[BudgetValue]) FOR [Period] IN ( [P_00], [P_01], [P_02], [P_03], [P_04], [P_05], [P_06], [P_07], [P_08], [P_09], [P_10], [P_11], [P_12], [P_13] ) ) [piv];


-- dbo.ProCure_INIS_vwSeminar_original1 source

ALTER VIEW [dbo].[ProCure_INIS_vwSeminar]
			AS
			SELECT dbo.ProCure_INIS_Seminar.OID AS Nr, (dbo.ProCure_WebLink.Link + '/Seminar/Seminar.aspx?ID=' + CONVERT(NVARCHAR,dbo.ProCure_INIS_Seminar.OID)) AS CTSpecificVar5, dbo.ProCure_INIS_Seminar.Name AS Title, dbo.ProCure_INIS_Seminar.Name AS PaginaTitel, dbo.ProCure_INIS_Seminar.Subject AS Body, 
				  dbo.ProCure_INIS_Seminar.DateField1 AS ShowFrom, dbo.ProCure_INIS_Seminar.DateField2 AS ShowUntil, ISNULL(dbo.ProCure_INIS_Seminar.LocationStreet + ', ', '') + + ISNULL(dbo.ProCure_City.Postcode + ' ', '') 
				  + + ISNULL(dbo.ProCure_City.Name + ', ', '') + + ISNULL(dbo.ProCure_INIS_Seminar.LocationBuilding + ', ', '') + + ISNULL(dbo.ProCure_INIS_Seminar.LocationFloor + ', ', '') 
				  + + ISNULL(dbo.ProCure_INIS_Seminar.LocationRoom, '') AS CTSpecificVar2, dbo.ProCure_INIS_Seminar.StartTime AS CTSpecificDate1, dbo.ProCure_INIS_Seminar.EndTime AS CTSpecificDate2, 
				  dbo.ProCure_INIS_Seminar.BitField5 AS agenda_Home, dbo.ProCure_INIS_Seminar.BitField1 AS agenda_PXL_Congress, dbo.ProCure_INIS_Seminar.BitField2 AS agenda_PXL_Research, 
				  dbo.ProCure_INIS_Seminar.BitField3 AS agenda_Studenten, dbo.ProCure_INIS_Seminar.BitField4 AS agenda_Toekomstige_Studenten, dbo.ProCure_INIS_Seminar.BitField6 AS sfeerblok_dpt_Business, 
				  dbo.ProCure_INIS_Seminar.BitField7 AS sfeerblok_dpt_Education, dbo.ProCure_INIS_Seminar.BitField8 AS sfeerblok_dpt_Healthcare, dbo.ProCure_INIS_Seminar.BitField9 AS sfeerblok_dpt_IT, 
				  dbo.ProCure_INIS_Seminar.BitField10 AS sfeerblok_dpt_MAD, dbo.ProCure_INIS_Seminar.BitField11 AS sfeerblok_dpt_MediaTourism, dbo.ProCure_INIS_Seminar.BitField12 AS sfeerblok_dpt_Music, 
				  dbo.ProCure_INIS_Seminar.BitField13 AS sfeerblok_dpt_SocialWork, dbo.ProCure_INIS_Seminar.BitField14 AS sfeerblok_dpt_Tech, dbo.ProCure_INIS_Seminar.StringField1 as Thema
			FROM     dbo.ProCure_INIS_Seminar LEFT OUTER JOIN
				  dbo.ProCure_City ON dbo.ProCure_INIS_Seminar.OID = dbo.ProCure_City.OID LEFT OUTER JOIN
				  dbo.ProCure_Country ON dbo.ProCure_City.Country = dbo.ProCure_Country.OID LEFT OUTER JOIN
				  dbo.ProCure_WebLink ON dbo.ProCure_WebLink.OID = dbo.ProCure_INIS_Seminar.WebLink;


